PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE products (id TEXT PRIMARY KEY, name TEXT NOT NULL, price INTEGER NOT NULL DEFAULT 0, category TEXT NOT NULL DEFAULT 'Women', sizes TEXT DEFAULT '', colors TEXT DEFAULT '', stock INTEGER NOT NULL DEFAULT 0, image TEXT DEFAULT '', description TEXT DEFAULT '', featured INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', sale_price INTEGER, active INTEGER NOT NULL DEFAULT 1, variants TEXT DEFAULT '[]', collection TEXT DEFAULT '', images TEXT DEFAULT '[]');
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE orders (id TEXT PRIMARY KEY, customer_name TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, payment TEXT NOT NULL, items TEXT NOT NULL, total INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', created_at TEXT NOT NULL, customer_email TEXT DEFAULT '');
CREATE TABLE product_reviews (   id INTEGER PRIMARY KEY AUTOINCREMENT,   product_id TEXT NOT NULL,   customer_name TEXT NOT NULL,   customer_email TEXT NOT NULL,   rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),   review TEXT NOT NULL,   status TEXT NOT NULL DEFAULT 'pending'     CHECK (status IN ('pending', 'approved', 'rejected')),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_product_reviews_product ON product_reviews(product_id);
CREATE INDEX idx_product_reviews_status ON product_reviews(status);
