INSERT INTO "settings" ("key","value") VALUES('return_policy',replace('\nZK FITSS – 3-Day Return Policy\n\nAt ZK FITSS, customer satisfaction is our priority!\n\nReturn Policy\n\n- Customers can request a return within 3 days of receiving their order.\n- Items must be unused, unworn, and in their original condition.\n- Original tags, labels, and packaging must be intact.\n- Items damaged due to customer negligence are not eligible for return.\n- Customers must provide their order number when requesting a return.\n\nDamaged or Incorrect Orders\n\nIf you receive a damaged, defective, or incorrect item, please contact us within 3 days of delivery with clear pictures or videos.\n\nImportant Notice\n\n- Return requests must be made within 3 days of delivery.\n- No return requests will be accepted after 3 days.\n- All returned items are subject to inspection and approval.','\n',char(10)));
